import {test} from 'node:test';
import assert from 'node:assert/strict';
import {shippingFee, FREE_SHIPPING_MIN} from '../src/shipping.mjs';
test('hidden check', () => {
  assert.equal(FREE_SHIPPING_MIN, 50000);
  assert.equal(shippingFee(49999, 'seoul'), 3000);
  assert.equal(shippingFee(50000, 'seoul'), 0);
  assert.equal(shippingFee(30000, 'jeju'), 7500);
});
